// Object.prototype.toString：靠内部类型标签判断，必须用 call 把 this 绑到待测值上
const getType = (x) => Object.prototype.toString.call(x);

// 若题面要 'array' 这种短标签：getType(x).slice(8, -1).toLowerCase()

// instanceof：沿 __proto__ 链查找是否等于 R.prototype
const myInstanceof = (L, R) => {
  const proto = R.prototype; // 右侧构造函数的 prototype
  for (let o = Object.getPrototypeOf(L); o; o = Object.getPrototypeOf(o)) {
    if (o === proto) return true; // 链上某环和目标 prototype 相同
  }
  return false; // 查到 null 还没命中
};

// myCall：将待调用函数临时挂载至 ctx，使 this 指向 ctx
Function.prototype.myCall = function (ctx, ...args) {
  const o = ctx == null ? globalThis : Object(ctx); // 非严格模式：null/undefined 绑定全局对象、原始值装箱；严格模式原样保留 thisArg
  const k = Symbol('__fn__'); // 唯一键，降低与对象自有属性冲突概率
  o[k] = this; // 当前函数变为 o 的方法
  try {
    return o[k](...args); // 以方法形式调用，this === o
  } finally {
    delete o[k]; // 无论成败均清理临时属性
  }
};

// myApply：第二参为数组或类数组，展开后复用 myCall
Function.prototype.myApply = function (ctx, arr) {
  return this.myCall(ctx, ...Array.from(arr ?? []));
};

// myBind：闭包保存原函数 fn 与预设参数 a1
Function.prototype.myBind = function (ctx, ...a1) {
  const fn = this;
  const bound = function (...a2) {
    // new bound() 时 this 为实例，走构造路径；普通调用使用绑定的 ctx
    return fn.apply(this instanceof bound ? this : ctx, [...a1, ...a2]);
  };
  // 使 bound 实例能 instanceof 原构造函数：共享原型链（fn 无 prototype 时跳过）
  if (fn.prototype) bound.prototype = Object.create(fn.prototype);
  return bound;
};

// myNew：Ctor 是构造函数，args 是构造参数
const myNew = (Ctor, ...args) => {
  const o = Object.create(Ctor.prototype); // 实例的原型链指向 Ctor.prototype
  const r = Ctor.apply(o, args); // 执行构造函数，可能往 o 上挂属性
  // 规范：只有返回值是对象或函数时才用返回值，否则用 o
  return r != null && (typeof r === 'object' || typeof r === 'function') ? r : o;
};

// Object.create：空对象原型指向 proto（new 第一步同类）
const create = (proto) => {
  const F = function () {};
  F.prototype = proto;
  return new F();
};

// flatten：仍是数组且剩余深度 > 0 就继续递归，否则当作叶子元素
const flatten = (arr, d = Infinity) =>
  arr.flatMap((v) =>
    Array.isArray(v) && d > 0 ? flatten(v, d - 1) : [v],
  );

// JSON.parse(JSON.stringify)：写法简单，但丢类型、不能处理循环引用
// 递归 + WeakMap：在对象图上深拷贝，避免环导致栈溢出
const clone = (x, seen = new WeakMap()) => {
  if (x == null || typeof x !== 'object') return x; // 原始值或 null
  if (seen.has(x)) return seen.get(x); // 遇到环：返回已经建好的副本
  if (Array.isArray(x)) {
    const a = [];
    seen.set(x, a); // 先登记，再递归填槽，处理自引用数组
    x.forEach((v, i) => (a[i] = clone(v, seen)));
    return a;
  }
  const o = {};
  seen.set(x, o);
  for (const k of Object.keys(x)) o[k] = clone(x[k], seen); // 只拷贝自有可枚举字符串键
  return o;
};

// 深比较：先 ===（同一引用或严格相等；NaN 需题面单独约定）
const isEqual = (a, b) => {
  if (a === b) return true; // 同一引用或严格相等（NaN 仍不相等）
  if (a == null || b == null || typeof a !== 'object' || typeof b !== 'object') return false;
  const ak = Object.keys(a),
    bk = Object.keys(b);
  if (ak.length !== bk.length) return false; // 可枚举键数量要一致
  return ak.every((k) => Object.hasOwn(b, k) && isEqual(a[k], b[k])); // 键名与子值都递归比较；用 hasOwn 只看自有属性
};

const listToTree = (list, rootPid = null) => {
  // 先建 id → 节点，方便 O(1) 挂父子
  const map = new Map(list.map((x) => [x.id, { ...x, children: [] }]));
  const roots = [];
  for (const node of map.values()) {
    // 无父或父不在表中 → 根；否则挂到父.children
    if (node.parentId == rootPid || !map.has(node.parentId)) roots.push(node);
    else map.get(node.parentId).children.push(node);
  }
  return roots;
};
const treeToList = (roots) => {
  const out = [];
  const walk = (nodes, parentId = null) => {
    for (const n of nodes || []) {
      const { children, ...rest } = n; // 展开时丢掉 children 字段
      out.push({ ...rest, parentId });
      walk(children, n.id);
    }
  };
  walk(roots, null);
  return out;
};

// 柯里化：fn.length 是形参个数；用 function 才能保留调用时的 this
const curry = (fn) =>
  function curried(...a) {
    if (a.length >= fn.length) return fn.apply(this, a); // 参数凑够了，执行原函数
    return (...b) => curried.apply(this, [...a, ...b]); // 还没够，继续收参
  };

// 链式累加：空调用 () 返回累计和；继续传参则返回同一个累加函数
function createAdder(sum = 0) {
  const add = (n) => {
    if (n === undefined) return sum; // add() 表示结束链，给出结果
    sum += n;
    return add; // add(1)(2) 还能继续调用
  };
  return add;
}
// 示例：const add = createAdder(); add(1)(2)(3)() === 6

// debounce：每次触发均重置定时器，仅在停顿满 wait 毫秒后执行
const debounce = (fn, wait) => {
  let t; // 保存定时器 id
  return function (...args) {
    clearTimeout(t); // 新一轮输入，取消上一次待执行回调
    t = setTimeout(() => fn.apply(this, args), wait); // 保留调用方 this 与参数
  };
};

// 写法一：时间戳版——距上次执行满 wait 才放行，首次调用立即执行
const throttle = (fn, wait) => {
  let prev = 0;
  return function (...args) {
    const now = Date.now();
    if (now - prev >= wait) {
      prev = now; // 记录本次执行时刻
      fn.apply(this, args);
    }
  };
};

// 写法二：定时器版——执行后 wait 内忽略后续触发，适用于「执行完再冷却」
const throttleTimer = (fn, wait) => {
  let t;
  return function (...args) {
    if (t) return; // 冷却期内
    fn.apply(this, args); // 立即执行一次
    t = setTimeout(() => {
      t = null; // 冷却结束，允许下次触发
    }, wait);
  };
};

// 教学示意：演示 pending → fulfilled / rejected 两条路径与微任务调度
class MyPromise {
  constructor(executor) {
    this._state = 'pending' // 等待中
    this._value = undefined
    this._cb = []
    const settle = (state, v) => {
      if (this._state !== 'pending') return // 只能结算一次
      this._state = state
      this._value = v
      // 微任务里刷 then 回调，保证异步性
      queueMicrotask(() => this._cb.splice(0).forEach((fn) => fn()))
    }
    const resolve = (v) => settle('fulfilled', v)
    const reject = (e) => settle('rejected', e)
    try {
      executor(resolve, reject)
    } catch (e) {
      reject(e) // executor 同步 throw → rejected
    }
  }
  then(onFulfilled, onRejected) {
    return new MyPromise((resolve, reject) => {
      const run = () => {
        const fn = this._state === 'fulfilled' ? onFulfilled : onRejected
        // 回调缺失则把状态与值透传给下一环
        if (fn == null) {
          ;(this._state === 'fulfilled' ? resolve : reject)(this._value)
          return
        }
        try {
          // 简化：未做 thenable 展开，完整实现见 Promise/A+
          resolve(fn(this._value))
        } catch (e) {
          reject(e)
        }
      }
      // 未结算则排队；已结算则下一微任务执行
      this._state === 'pending' ? this._cb.push(run) : queueMicrotask(run)
    })
  }
  catch(onRejected) {
    return this.then(null, onRejected)
  }
}

// Promise.race：以最先完成（fulfilled 或 rejected）的结果决定整体状态
const promiseRace = (arr) =>
  new Promise((resolve, reject) => {
    // Promise.resolve：将普通值包装为 pending→fulfilled
    for (const p of arr) Promise.resolve(p).then(resolve, reject);
    // 任一先完成即触发外层；后续结果被忽略（状态不可逆）
  });

// Promise.all：全部 fulfilled 后 resolve；任一项 rejected 则立即 reject
const promiseAll = (arr) =>
  new Promise((resolve, reject) => {
    const out = [];
    let n = arr.length;
    if (!n) return resolve(out); // 空数组：直接 fulfilled
    arr.forEach((p, i) =>
      Promise.resolve(p).then(
        (v) => {
          out[i] = v;
          if (--n === 0) resolve(out); // 全部 fulfilled
        },
        reject, // 首个 rejected 传递给外层
      ),
    );
  });

// allSettled：单项 rejected 也不让整体 reject；用 Promise.all 包一层
const allSettled = (arr) =>
  Promise.all(
    arr.map((p) =>
      Promise.resolve(p).then(
        (value) => ({ status: 'fulfilled', value }), // 成功也包成对象
        (reason) => ({ status: 'rejected', reason }), // 失败转成 fulfilled 结果项
      ),
    ),
  );

// 串行：for...of + await，每次循环会等上一个 await 结束再往下走
const runSeries = async (tasks) => {
  const out = [];
  for (const t of tasks) {
    out.push(await t()); // await 会暂停当前 async 函数，后续代码作为微任务继续
  }
  return out;
};

const pool = async (limit, tasks) => {
  const ret = new Array(tasks.length);
  let i = 0; // 共享下标，多 worker 抢任务
  const workers = Array.from({ length: Math.min(limit, tasks.length) }, async () => {
    while (i < tasks.length) {
      const cur = i++; // 先占坑再 await，保证结果顺序
      ret[cur] = await tasks[cur]();
    }
  });
  await Promise.all(workers);
  return ret;
};

// 重试：try/catch 配合递归；attempts 为总尝试次数（含首次）
const retry = async (fn, attempts = 3, delayMs = 0) => {
  try {
    return await fn();
  } catch (e) {
    if (attempts <= 1) throw e; // 次数耗尽，原样抛出
    if (delayMs) await new Promise((r) => setTimeout(r, delayMs)); // 两次尝试间等待
    return retry(fn, attempts - 1, delayMs); // 递归：次数减一后重试
  }
};

// EventEmitter：Map<事件名, Set<回调>>
class EventEmitter {
  constructor() {
    this._m = new Map();
  }
  on(ev, fn) {
    const s = this._m.get(ev) ?? new Set(); // 没有就新建监听集合
    s.add(fn);
    this._m.set(ev, s);
    return this; // 支持链式调用
  }
  off(ev, fn) {
    this._m.get(ev)?.delete(fn);
    return this;
  }
  emit(ev, ...args) {
    const s = this._m.get(ev);
    if (!s || !s.size) return false; // 没有监听
    [...s].forEach((fn) => fn(...args)); // 先快照再遍历，避免回调里改 Set 破坏遍历
    return true;
  }
}
